#!/usr/bin/env python3
import argparse,json,re,subprocess,sys
from pathlib import Path
sys.dont_write_bytecode=True
from source_extract import function,array,macros,enum_containing,identity,COMMIT,verify
p=argparse.ArgumentParser();p.add_argument('reference',type=Path);a=p.parse_args();r=a.reference;out=Path(__file__).resolve().parent
paths=['src/battle_anim.c','src/battle_anim_effects_1.c','src/battle_anim_effects_3.c','src/battle_anim_water.c','src/battle_anim_mons.c','src/palette.c','src/blend_palette.c','include/palette.h','include/battle_anim.h','include/gba/types.h','include/gba/io_reg.h','include/gba/defines.h','include/constants/battle.h','include/constants/battle_anim.h','include/constants/rgb.h'];verify(r,paths);s={p:(r/p).read_text() for p in paths}
funcs={'src/battle_anim.c':['BattleAnimAdjustPanning'],'src/battle_anim_effects_3.c':['AnimTask_MorningSunLightBeam'],'src/battle_anim_effects_1.c':['AnimTask_MoonlightEndFade','AnimTask_MoonlightEndFade_Step'],'src/battle_anim_mons.c':['GetBattleAnimBg1Data','GetBattlePalettesMask','GetBattleMonSpritePalettesMask','AnimTask_AlphaFadeIn','AnimTask_AlphaFadeIn_Step'],'src/battle_anim_water.c':['AnimTask_RotateAuroraRingColors','AnimTask_RotateAuroraRingColors_Step'],'src/palette.c':['UpdatePaletteFade','BeginNormalPaletteFade','UpdateNormalPaletteFade','IsSoftwarePaletteFadeFinishing','BlendPalettes'],'src/blend_palette.c':['BlendPalette']}
bodies=[function(s[p],n) for p,ns in funcs.items() for n in ns];protos='\n'.join(f[:f.index('{')].strip()+';' for f in bodies)
defs=macros(list(s.values()),['BLDCNT_TGT1_BG1','BLDCNT_EFFECT_BLEND','BLDCNT_TGT2_ALL','BLDALPHA_BLEND','REG_OFFSET_BLDCNT','REG_OFFSET_BLDALPHA','BG_PLTT_ID','OBJ_PLTT_ID','PLTT_SIZE_4BPP','PLTT_SIZE','B_SIDE_PLAYER','BATTLE_PARTNER','BG_ANIM_PAL_1','BG_ANIM_PAL_2','B_POSITION_PLAYER_LEFT','B_POSITION_PLAYER_RIGHT','B_POSITION_OPPONENT_LEFT','B_POSITION_OPPONENT_RIGHT','ANIM_TAG_MOON','ANIM_TAG_GREEN_SPARKLE','ANIM_TAG_RAINBOW_RINGS','gPaletteFade_selectedPalettes','gPaletteFade_delay','PALETTE_FADE_STATUS_LOADING','PALETTE_FADE_STATUS_DONE','PALETTE_FADE_STATUS_ACTIVE','RGB','SOUND_PAN_ATTACKER','SOUND_PAN_TARGET','B_SIDE_OPPONENT'])
types=enum_containing(s['include/battle_anim.h'],'BG_ANIM_PRIORITY')+enum_containing(s['src/palette.c'],'NORMAL_FADE')
types+=re.search(r'struct PaletteFadeControl\s*\{[\s\S]*?\n\};',s['include/palette.h'])[0]+'\n';h=s['include/gba/types.h'];types+=h[h.index('struct PlttData'):h.index('struct OamData')]
c=(out/'tasks-prefix.c.in').read_text().replace('@DEFINES@',defs).replace('@TYPES@',types).replace('@PROTOTYPES@',protos).replace('@ARRAYS@',array(s['src/battle_anim_effects_3.c'],'sMorningSunLightBeamCoordsTable')).replace('@FUNCTIONS@','\n'.join(bodies));(out/'tasks.c').write_text(c)
for opt in ['O0','O2']:subprocess.run(['cc','-std=c11','-'+opt,'-fwrapv','-Wno-int-to-pointer-cast',str(out/'tasks.c'),'-o',str(out/('tasks-'+opt))],check=True)
cases=[]
for kind in range(4):
 for actor in range(4):
  for visible in ([3,15] if kind==1 else [15]):
   for preexisting in ([0,1] if kind==1 else [0]):
    raw=[subprocess.check_output([str(out/('tasks-'+opt)),*map(str,[kind,actor,visible,preexisting])]) for opt in ['O0','O2']];assert raw[0]==raw[1];rows=[json.loads(x) for x in raw[0].splitlines()];cases.append(dict(kind=kind,attacker=actor,target=actor^1,visibleMask=visible,preexistingFade=bool(preexisting),rows=rows))
result=dict(schema='firered-recovery-tasks-palette-source-v1',commit=COMMIT,sources=identity(r,paths),source_functions=funcs,optimization_parity=['O0','O2'],semantics={'kinds':['morning-sun-bg','moonlight-end-fade','alpha-fade-in','aurora-palette-rotation'],'frame0':'Immediate initializer before regular frame; later rows update global palette fade before task callback','paletteBanks':[1,2,3,16,17,18,19,20,21,22],'taskData':'Sixteen native signed words','stubs':['source palette transfer buffer copied into local1024byte memory; pending transfer is cleared before each frame to model completed VBlank','source IsContest is false, visibility supplied explicitly, battler positions map identity; all health box statusAnimActive flags are false for these move roots','three tagged object palettes use slots4(Moon),5(Sparkle),6(Rainbow)','Moon/Sparkle scene scan receives four matching objects plus one foreign template; signal values retained','source pointer-variable helpers encode the uint32 mask in two16-bit words, avoiding host pointer width assumptions','BG loads record literal asset identity, banks and offsets; material bytes have a separate independent oracle']},cases=cases)
(out/'tasks-vectors.json').write_text(json.dumps(result,separators=(',',':'))+'\n');print('tasks',len(cases),sum(len(c['rows']) for c in cases))
